(()=>{const key='gramin-service-branch',base={name:'Narsipatnam branch',latitude:17.667,longitude:82.612},read=()=>{try{const x=JSON.parse(localStorage.getItem(key)||'null');return Number.isFinite(x?.latitude)&&Number.isFinite(x?.longitude)?x:base;}catch{return base;}},save=x=>localStorage.setItem(key,JSON.stringify(x));window.graminLocation={get:read};const close=()=>document.querySelector('#location-picker')?.remove(),update=()=>{const h=document.querySelector('header .location');if(!h)return;if(!localToken||!localUser||role!=='customer'){h.textContent='';close();return;}const branch=read();h.innerHTML=`<button type="button" class="location-control" id="change-location">⌖ ${esc(branch.name)}<small>50 km service area · Change</small></button>`;document.querySelector('#change-location').onclick=picker;};function picker(){close();const p=document.createElement('section');p.id='location-picker';p.className='location-picker';p.innerHTML='<div class="row"><strong>Change service branch</strong><button type="button" class="quiet" id="close-location">Close</button></div><label class="field">Town or village<input id="location-query" autocomplete="off" placeholder="Type your town or village"></label><div id="location-results" class="place-options" role="listbox"></div><p class="muted">Address-village suggestions remain within 50 km of this branch.</p>';document.body.append(p);document.querySelector('#close-location').onclick=close;const i=document.querySelector('#location-query'),r=document.querySelector('#location-results');let timer,controller;i.oninput=()=>{clearTimeout(timer);controller?.abort();const q=i.value.trim();r.innerHTML='';if(q.length<3)return;timer=setTimeout(async()=>{controller=new AbortController();try{const res=await fetch('/api/places?q='+encodeURIComponent(q),{headers:{Authorization:'Bearer '+token()},signal:controller.signal}),body=await res.json();if(!res.ok)throw Error();r.innerHTML=(body.places||[]).map((x,n)=>`<button type="button" class="location-result" data-n="${n}"><strong>${esc(x.name)}</strong><small>${esc(x.label)}</small></button>`).join('')||'<p class="muted">No matching location found.</p>';r.querySelectorAll('[data-n]').forEach(b=>b.onclick=()=>{const x=body.places[Number(b.dataset.n)];save({name:x.name,latitude:x.latitude,longitude:x.longitude});close();update();toast('Service branch changed. Village suggestions use its 50 km area.');});}catch(e){if(e.name!=='AbortError')r.innerHTML='<p class="muted">Location search is unavailable.</p>';};},350);};i.focus();}const baseRender=render;render=function(){baseRender();update();};update();})();
